import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"迁移你的云存储","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/usage/remote-migration.md","filePath":"zh-Hans/usage/remote-migration.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/usage/remote-migration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="迁移你的云存储" tabindex="-1">迁移你的云存储 <a class="header-anchor" href="#迁移你的云存储" aria-label="Permalink to “迁移你的云存储”">​</a></h1><p>一些功能，例如<a href="./../deep-dive/asymmetric-storage">非对称存储</a>和<a href="./../deep-dive/modules/encryption">加密</a>，要求远端存储采用不同的格式。当你开启这些功能但远端仍是不兼容的格式时，Sync Engine 可能产生灾难性的同步结果。</p><p>Sync Engine 自身不会尝试自动迁移远端格式。原因是同步策略可能因设备而异，一台设备上的 Sync Engine 无法可靠地完成迁移，还可能把远端或其他设备留在损坏的中间状态。这一点将来可能改进，但目前开启这些功能时必须手动迁移。</p><p>本页详述如何用 Sync Engine 安全地完成手动迁移。</p><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to “步骤”">​</a></h2><ol><li>在所有设备上执行同步，确保它们都持有最新的文件集合。</li><li>选择文件最多、网络最好的一台设备作为主操作设备，在其余设备上退出 Obsidian。</li><li>在这台设备上临时关闭实时同步和定时同步，避免意外干扰。</li><li>临时调整<a href="./settings#同步策略">同步策略</a>并执行同步，确保这台设备上的仓库持有你需要上传到远端的<strong>完整文件集合</strong>。完成后，调整同步策略，确保<strong>&quot;镜像本地&quot;策略应用到这整个文件集合</strong>。</li><li><strong>在开发设置中找到<a href="./settings#清除记录">清除记录</a>，点击&quot;清除&quot;</strong>。</li><li>把整个文件集合复制到别处作为备份。</li><li>进入云存储的文件管理界面，<strong>手动删除所有之前同步过的文件，或直接删除根目录</strong>。</li><li>开启改变远端格式的功能（例如加密或非对称存储），应该会弹出迁移提醒，点击&quot;确认&quot;。</li><li>现在触发一次手动同步，应该会显示一个充满上传操作的预览。检查要上传的文件并开始同步，等待批量上传完成。</li><li><strong>关闭其他所有设备的网络连接，并在每台设备上进入 Obsidian</strong>，开启你要迁移的同一个功能。</li><li>恢复这些设备的网络连接，各自启动一次手动试同步。同步应以 &quot;Already synced&quot; 完成，没有额外操作。</li><li>在主设备上恢复同步策略和实时 / 定时同步设置。迁移到此完成。</li></ol>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};